package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Path;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.mock.env.MockEnvironment;
class SqlSessionsTest {
 @TempDir Path root;
 MockEnvironment env(boolean postgres)throws Exception{var migration=new MigrationsTest();migration.root=root;return migration.configuration(postgres);}
 @org.junit.jupiter.api.Test void secureCookieDefaults(){var configuration=new SharedSessions();var response=new org.springframework.mock.web.MockHttpServletResponse();configuration.cookieSerializer(new MockEnvironment()).writeCookieValue(new org.springframework.session.web.http.CookieSerializer.CookieValue(new org.springframework.mock.web.MockHttpServletRequest(),response,"opaque-session"));String cookie=response.getHeader("Set-Cookie");assertTrue(cookie.contains("JSESSIONID=opaque-session"));assertTrue(cookie.contains("Secure"));assertTrue(cookie.contains("HttpOnly"));assertTrue(cookie.contains("SameSite=Lax"));assertTrue(cookie.contains("Path=/"));}
 @ParameterizedTest @ValueSource(booleans={false,true}) void persistsMergesRotatesAndDeletes(boolean postgres)throws Exception{
  var environment=env(postgres);var store=new Store(environment);var repository=new SqlSessions(store);assertNull(repository.findById(null));assertNull(repository.findById("invalid"));assertNull(repository.findById(UUID.randomUUID().toString()));var session=repository.createSession();assertFalse(session.isExpired());session.setAttribute("csrf","private-csrf-token");session.setAttribute("auth_revision",1L);repository.save(session);String original=session.getId();try(var db=store.open()){var row=db.one("SELECT * FROM os_shared_session");assertFalse(row.toString().contains(original));assertFalse(row.toString().contains("private-csrf-token"));assertEquals(Passwords.tokenHash(original),row.get("session_hash"));}
  var other=new SqlSessions(new Store(environment));var one=repository.findById(original);var two=other.findById(original);assertEquals(1L,(Object)one.getAttribute("auth_revision"));assertEquals(session.getCreationTime().toEpochMilli(),one.getCreationTime().toEpochMilli());one.setAttribute("left","left value");two.setAttribute("right","right value");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->repository.save(one));var b=pool.submit(()->other.save(two));a.get();b.get();}var combined=other.findById(original);assertEquals("left value",combined.getAttribute("left"));assertEquals("right value",combined.getAttribute("right"));combined.removeAttribute("left");repository.save(combined);assertNull(other.findById(original).getAttribute("left"));var stale=other.findById(original);combined.changeSessionId();repository.save(combined);assertNull(other.findById(original));assertNotNull(other.findById(combined.getId()));stale.setAttribute("user","must-not-return");other.save(stale);assertNull(repository.findById(original));var deleted=other.findById(combined.getId());repository.deleteById(combined.getId());other.save(deleted);assertNull(repository.findById(combined.getId()));repository.deleteById(combined.getId());
  var expired=repository.createSession();repository.save(expired);try(var db=store.open()){db.update("UPDATE os_shared_session SET expires_at=0 WHERE session_hash=?",Passwords.tokenHash(expired.getId()));db.connection.commit();}assertNull(repository.findById(expired.getId()));try(var db=store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_shared_session"));}
 }
 @ParameterizedTest @ValueSource(booleans={false,true}) void boundsCorruptionAndUnavailableStore(boolean postgres)throws Exception{
  var store=new Store(env(postgres));var repository=new SqlSessions(store);var session=repository.createSession();session.setAttribute("bad",1);assertThrows(IllegalArgumentException.class,()->repository.save(session));session.removeAttribute("bad");session.setAttribute("huge","x".repeat(65536));assertThrows(IllegalArgumentException.class,()->repository.save(session));session.removeAttribute("huge");session.setMaxInactiveInterval(Duration.ofSeconds(-1));assertThrows(IllegalArgumentException.class,()->repository.save(session));session.setMaxInactiveInterval(Duration.ofMillis(BrowserSessions.IDLE_MILLIS));repository.save(session);var a=repository.findById(session.getId());var b=repository.findById(session.getId());a.setAttribute("a","x".repeat(40000));b.setAttribute("b","y".repeat(40000));repository.save(a);assertThrows(IllegalStateException.class,()->repository.save(b));assertNull(repository.findById(session.getId()).getAttribute("b"));
  var second=repository.createSession();repository.save(second);String envelope;try(var db=store.open()){envelope=db.one("SELECT envelope FROM os_shared_session WHERE session_hash=?",Passwords.tokenHash(session.getId())).get("envelope").toString();db.update("UPDATE os_shared_session SET envelope=? WHERE session_hash=?",envelope,Passwords.tokenHash(second.getId()));db.connection.commit();}assertThrows(IllegalStateException.class,()->repository.findById(second.getId()));try(var db=store.open()){db.update("UPDATE os_shared_session SET envelope='corrupt' WHERE session_hash=?",Passwords.tokenHash(session.getId()));db.connection.commit();}assertThrows(IllegalStateException.class,()->repository.findById(session.getId()));
  try(var db=store.open()){db.update("DROP TABLE os_shared_session");db.connection.commit();}assertThrows(IllegalStateException.class,()->repository.findById(session.getId()));assertThrows(IllegalStateException.class,()->repository.save(repository.createSession()));assertThrows(IllegalStateException.class,()->repository.deleteById(session.getId()));
 }
 @ParameterizedTest @ValueSource(booleans={false,true}) void capacityCleanupAndUpgrade(boolean postgres)throws Exception{
  var environment=env(postgres);var store=new Store(environment);var repository=new SqlSessions(store);try(var db=store.open()){db.update("DROP TABLE os_shared_session");db.update("DELETE FROM os_migration WHERE version>=97");db.connection.commit();Migrations.apply(db);assertEquals(0,db.count("SELECT COUNT(*) FROM os_shared_session"));db.connection.rollback();assertEquals(96,db.count("SELECT MAX(version) FROM os_migration"));}store=new Store(environment);repository=new SqlSessions(store);var retained=repository.createSession();retained.setAttribute("csrf","survives-restart");repository.save(retained);var latest=repository;try(var db=store.open()){for(int n=0;n<9999;n++)db.update("INSERT INTO os_shared_session(session_hash,created_at,last_seen,expires_at,envelope) VALUES(?,?,?,?,?)",String.format("%064d",n),1L,1L,System.currentTimeMillis()+60000,"fixture");db.connection.commit();}assertThrows(IllegalStateException.class,()->latest.save(latest.createSession()));latest.save(retained);try(var db=store.open()){db.update("UPDATE os_shared_session SET expires_at=0 WHERE envelope='fixture'");db.connection.commit();}latest.save(latest.createSession());var reopened=new SqlSessions(new Store(environment));assertEquals("survives-restart",reopened.findById(retained.getId()).getAttribute("csrf"));try(var db=store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_shared_session"));assertEquals(Migrations.VERSION,db.count("SELECT MAX(version) FROM os_migration"));}
 }
}
